1618	  <script>
1619	document.addEventListener('DOMContentLoaded', function () {
1620	  const itemsPerPage = 8;
1621	  const wrapper = document.getElementById('cms-wrapper');
1622	  let currentPage = 1;
1623	  let activeItems = [];
1624	  let isOurUpdate = false;
1625	  function getNav() {
1626	    let nav = document.getElementById('custom-pagination');
1627	    if (!nav) {
1628	      nav = document.createElement('div');
1629	      nav.id = 'custom-pagination';
1630	      nav.style.cssText = 'display:flex;align-items:center;justify-content:center;gap:8px;margin-top:40px;';
1631	      wrapper.parentNode.insertBefore(nav, wrapper.nextSibling);
1632	    }
1633	    return nav;
1634	  }
1635	  function getFinsweetVisibleItems() {
1636	    const all = [...wrapper.querySelectorAll('.work-cms-item')];
1637	    all.forEach(item => {
1638	      if (item.style.getPropertyPriority('display') === 'important') {
1639	        item.style.removeProperty('display');
1640	      }
1641	    });
1642	    return all.filter(item => window.getComputedStyle(item).display !== 'none');
1643	  }
1644	  function applyPage(page, items) {
1645	    const start = (page - 1) * itemsPerPage;
1646	    items.forEach((item, i) => {
1647	      if (i >= start && i < start + itemsPerPage) {
1648	        item.style.removeProperty('display');
1649	      } else {
1650	        item.style.setProperty('display', 'none', 'important');
1651	      }
1652	    });
1653	  }
1654	  function showPage(page) {
1655	    currentPage = page;
1656	    isOurUpdate = true;
1657	    applyPage(page, activeItems);
1658	    // Re-apply after 50ms in case Finsweet immediately overrides
1659	    setTimeout(() => {
1660	      applyPage(page, activeItems);
1661	      isOurUpdate = false;
1662	    }, 50);
1663	    // Re-apply after 200ms as final safety net
1664	    setTimeout(() => {
1665	      applyPage(page, activeItems);
1666	    }, 200);
1667	    renderPagination();
1668	    wrapper.scrollIntoView({ behavior: 'smooth', block: 'start' });
1669	  }
1670	  function renderPagination() {
1671	    const nav = getNav();
1672	    nav.innerHTML = '';
1673	    const totalPages = Math.ceil(activeItems.length / itemsPerPage);
1674	    if (totalPages <= 1) {
1675	      nav.style.display = 'none';
1676	      return;
1677	    }
1678	    nav.style.display = 'flex';
1679	    const makeBtn = (label, targetPage, isActive, isDisabled) => {
1680	      const b = document.createElement('button');
1681	      b.textContent = label;
1682	      b.style.cssText = `
1683	        width:44px;height:44px;border-radius:12px;border:none;cursor:pointer;
1684	        font-size:15px;font-weight:600;font-family:inherit;
1685	        background:${isActive ? '#1a3a6e' : 'white'};
1686	        color:${isActive ? 'white' : '#1a3a6e'};
1687	        box-shadow:0 2px 8px rgba(0,0,0,0.08);
1688	        opacity:${isDisabled ? '0.4' : '1'};
1689	        pointer-events:${isDisabled ? 'none' : 'auto'};
1690	        transition:all 0.15s;
1691	      `;
1692	      if (!isActive && !isDisabled) {
1693	        b.addEventListener('click', () => showPage(targetPage));
1694	      }
1695	      return b;
1696	    };
1697	    nav.appendChild(makeBtn('<<', currentPage - 1, false, currentPage === 1));
1698	    for (let i = 1; i <= totalPages; i++) {
1699	      nav.appendChild(makeBtn(i, i, i === currentPage, false));
1700	    }
1701	    nav.appendChild(makeBtn('>>', currentPage + 1, false, currentPage === totalPages));
1702	  }
1703	  function rebuildPagination() {
1704	    if (isOurUpdate) return; // Don't rebuild while we're mid-page-change
1705	    activeItems = getFinsweetVisibleItems();
1706	    currentPage = 1;
1707	    showPage(1);
1708	  }
1709	  let debounce;
1710	  const observer = new MutationObserver(() => {
1711	    if (isOurUpdate) return;
1712	    clearTimeout(debounce);
1713	    debounce = setTimeout(rebuildPagination, 300);
1714	  });
1715	  setTimeout(() => {
1716	    rebuildPagination();
1717	    observer.observe(wrapper, {
1718	      attributes: true,
1719	      subtree: true,
1720	      attributeFilter: ['class', 'style']
1721	    });
1722	    document.querySelectorAll('input[fs-list-field]').forEach(cb => {
1723	      cb.addEventListener('change', () => {
1724	        setTimeout(rebuildPagination, 500);
1725	      });
1726	    });
1727	    document.querySelectorAll('[fs-list-element="clear"]').forEach(btn => {
1728	      btn.addEventListener('click', () => {
1729	        setTimeout(rebuildPagination, 500);
1730	      });
1731	    });
1732	  }, 1200);
1733	});
1734	</script>
1735	</body>
